  "usage_notes": [
    {
      "chord_quality": "dom7",
      "function_role": "harmonic-family-membership",
      "narrative": "Baker treats the dominant 7th as the most active chord of the tonality \u2014 'the V of a chord demands resolution, the I is final' \u2014 and as the gravitational center to which all chord cycles must eventually arrive before resolving to I. Chapter 8, p. 11.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:dominant-to-tonic-resolution"
