      "provenance": "extracted",
      "granularity_level": "d",
      "granularity_name": "color-tone-policy"
    },
    {
      "chord_quality": "dom7",
      "function_role": "forced-harmony-application",
      "narrative": "Baker prescribes Forced Harmony \u2014 'adding chords via progressions that move away from, then lead back into the tonic' \u2014 as the technique for keeping dom7 contexts active rather than static. When a passage would sit on a dominant chord as written, insert progressions that depart and return rather than sustaining the chord unchanged. Chapter 10, p. 14.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:forced-harmony-expansion"
      ],
      "source_work_id": "complete-course-in-jazz-guitar-vol-2",
