      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "ii-substitution-target",
      "narrative": "Baker establishes that 'the II chord can be readily substituted for the V,' permitting the supertonic chord to replace the dominant in a cycle provided the substituted chord still ultimately resolves to tonic. This makes dom7's substitution role bidirectional: it can receive the II or be displaced by it. Chapter 10, p. 14; Chapter 9, p. 12.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:ii-chord-insertion"
      ],
      "source_work_id": "complete-course-in-jazz-guitar-vol-2",
