      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "authentic-cadence-role",
      "narrative": "Baker prescribes using the dominant as the structural pivot of the Authentic Cadence: introductions stop on V before approaching the song's first chord, while endings 'approach the V and move on to the I, which is the final statement.' The dom7 is thus the obligatory penultimate chord in both cadential contexts. Chapter 12, p. 20.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:dominant-to-tonic-resolution"
      ],
      "source_work_id": "complete-course-in-jazz-guitar-vol-2",
