      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom9",
      "function_role": "harmonic-family-membership",
      "narrative": "Baker classifies dom9 as an Upper Partial form of the dominant \u2014 one of the extensions produced by building above the 7th \u2014 with the same tonic-resolution function as plain dom7. The 9th may be natural or flatted (dom7b9); both remain members of the Upper Partials family and resolve to I. Chapter 10, p. 14.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:upper-partials-dominant-alteration"
