    {
      "chord_quality": "min9",
      "function_role": "ninth-to-sixth-voice-leading-source",
      "narrative": "Baker prescribes the minor 9th as the starting point of the method's core modern voice-leading move: 'Each chord is moving from a minor ninth to a minor sixth chord, via passing tones.' The min9 is the departure chord; the min6 is the goal. Both the minor and major forms share this resolution structure, with mode as their only difference. Chapter 4, p. 7; Chapter 5, p. 8.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:ninth-to-sixth-voice-leading"
      ],
      "source_work_id": "complete-course-in-jazz-guitar-vol-2",
