      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "min6",
      "function_role": "song-form-closing-chord",
      "narrative": "Baker prescribes the minor 6th as the closing chord in song-form exercises: 'you are starting with the major or minor 9th and closing with the major or minor 6th.' The min6 provides the point of rest after the min9 departure. Chapter 7, p. 10.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:ninth-to-sixth-voice-leading"
      ],
      "source_work_id": "complete-course-in-jazz-guitar-vol-2",
