    {
      "chord_quality": "maj6",
      "function_role": "ninth-to-sixth-voice-leading-destination",
      "narrative": "Baker prescribes the major 6th as the tonic resolution of the major ninth in modern progressions. It is the harmonic goal reached via passing tones from maj9, replacing the simpler dominant-to-tonic arrival of standard progressions: 'moving from a major ninth via passing tones, to a major sixth.' Chapter 4, p. 7; Chapter 5, p. 8.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:ninth-to-sixth-voice-leading"
