    {
      "chord_quality": "maj6",
      "function_role": "relative-chord-equivalence",
      "narrative": "Baker establishes that 'the C6 chord and the Am7 chord have the same tones. They are called relatives for this reason.' The major 6th chord is thus enharmonically equivalent to the minor 7th built on its 6th degree \u2014 a relative substitution that underpins the method's chord-substitution vocabulary. Chapter 9, p. 12.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:ii-chord-insertion"
      ],
      "source_work_id": "complete-course-in-jazz-guitar-vol-2",
