      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "min7",
      "function_role": "relative-chord-equivalence",
      "narrative": "Baker teaches that Am7 and C6 share identical tones \u2014 'They are called relatives for this reason' \u2014 making min7 a direct substitute for its relative major 6th. Baker also notes that 'the three tones that form the Dm chord are the upper three tones of the G9 chord,' extending the relative-chord concept to upper-voice extraction from dominant extensions. Chapter 9, p. 12.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:ii-chord-insertion"
      ],
      "source_work_id": "complete-course-in-jazz-guitar-vol-2",
