      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "min7",
      "function_role": "ii-chord-function-in-ii-v-i",
      "narrative": "Baker prescribes the minor II chord as the preparatory chord before V in the I-II-V-I cycle, the progression 'in which we are most interested.' The II chord may be inserted before any dominant-to-tonic movement: 'it is possible to use the II chord instead of the V and resolve into the V from the II.' Min7 built on the second degree is the standard color for this role. Chapter 8, p. 11; Chapter 9, p. 12.",
      "source_principle_ids": [
        "mickey-baker:complete-course-vol-2:functional-diatonic-harmony:ii-chord-insertion"
      ],
      "source_work_id": "complete-course-in-jazz-guitar-vol-2",
